-- Enable RLS on all multi-tenant tables
ALTER TABLE declarations ENABLE ROW LEVEL SECURITY;
ALTER TABLE oga_permits ENABLE ROW LEVEL SECURITY;
ALTER TABLE payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE cargo_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_events ENABLE ROW LEVEL SECURITY;

-- declarations: traders see their own, officers see all
CREATE POLICY IF NOT EXISTS declarations_trader_select ON declarations
  FOR SELECT USING (trader_id = current_setting('app.current_user_id', true)::int OR
    current_setting('app.current_user_role', true) IN ('customs_officer','admin','inspector','finance'));

CREATE POLICY IF NOT EXISTS declarations_trader_insert ON declarations
  FOR INSERT WITH CHECK (trader_id = current_setting('app.current_user_id', true)::int);

CREATE POLICY IF NOT EXISTS declarations_trader_update ON declarations
  FOR UPDATE USING (trader_id = current_setting('app.current_user_id', true)::int OR
    current_setting('app.current_user_role', true) IN ('customs_officer','admin','inspector','finance'));

-- payments: traders see their own
CREATE POLICY IF NOT EXISTS payments_trader_select ON payments
  FOR SELECT USING (trader_id = current_setting('app.current_user_id', true)::int OR
    current_setting('app.current_user_role', true) IN ('admin','finance','customs_officer'));

CREATE POLICY IF NOT EXISTS payments_trader_insert ON payments
  FOR INSERT WITH CHECK (trader_id = current_setting('app.current_user_id', true)::int);

-- oga_permits: OGA officers see their agency permits, traders see their own
CREATE POLICY IF NOT EXISTS oga_permits_select ON oga_permits
  FOR SELECT USING (
    declaration_id IN (SELECT id FROM declarations WHERE trader_id = current_setting('app.current_user_id', true)::int) OR
    current_setting('app.current_user_role', true) IN ('oga_officer','admin','customs_officer')
  );

-- documents: owners see their own
CREATE POLICY IF NOT EXISTS documents_owner_select ON documents
  FOR SELECT USING (uploaded_by = current_setting('app.current_user_id', true)::int OR
    current_setting('app.current_user_role', true) IN ('admin','customs_officer','oga_officer'));

CREATE POLICY IF NOT EXISTS documents_owner_insert ON documents
  FOR INSERT WITH CHECK (uploaded_by = current_setting('app.current_user_id', true)::int);

-- notifications: users see their own
CREATE POLICY IF NOT EXISTS notifications_user_select ON notifications
  FOR SELECT USING (user_id = current_setting('app.current_user_id', true)::int);

-- audit_events: admins only
CREATE POLICY IF NOT EXISTS audit_events_admin_select ON audit_events
  FOR SELECT USING (current_setting('app.current_user_role', true) = 'admin');

CREATE POLICY IF NOT EXISTS audit_events_insert ON audit_events
  FOR INSERT WITH CHECK (true);

